algorithms.pseudocode:
function DualRegevEncrypt(A, p, mu, r):
    u <- sum_i r_i * A_i           // u_j = sum_i r_i * A_{ij}
    v <- <r, p> + mu               // v = sum_i r_i * p_i + mu
    return (u, v)

function DualRegevDecrypt(s, u, v):
    mu_prime <- v - <u, s>         // mu' = v - sum_j u_j * s_j
    return mu_prime
